#!/usr/bin/env python3
"""Generate a constraints file for the blink smoke test from a part's own pins.

nextpnr refuses to place a design with any unconstrained IO ("FIXME:
unconstrained IO not supported"), so a chipdb cannot be exercised at all
without an XDC naming real package pins. Hand-writing one per die does not
scale to 42 of them, and for most there is no board to copy a pinout from
anyway.

This picks usable pins out of package_pins.csv: ordinary IOB sites in an
IO_* function, skipping the transceiver pads (OPAD/IPAD), the configuration
and dedicated pins, and anything whose bank is not a normal IO bank. It is a
smoke test, not a board file - the assignment is arbitrary and the resulting
bitstream is not meant to be loaded into hardware. What it proves is that the
chipdb has real IO sites, that they are reachable, and that place-and-route
completes on the die.

The clock is put on a clock-capable pin where one is free, since a global
clock net driven from an ordinary IO will not route.

    env/gen_smoke_xdc.py <package_pins.csv> <out.xdc> [signal ...]

Signals default to the arty_s7_blink design: clk, rst, led[0..3].

The syntax matches what nextpnr's xilinx uarch actually parses, which is a
much smaller language than real XDC: "set_property LOC <pin> [get_ports
<name>]", no braces, no trailing comments. PACKAGE_PIN, braces around the
port name, or a ";#" comment all make it fail with "failed to parse target".
"""
import csv
import re
import sys


def usable(row):
    """An ordinary user IO, not a transceiver pad or a dedicated function."""
    site, fn, bank = row["site"], row["pin_function"] or "", row["bank"]
    if not site.startswith("IOB"):
        return False
    if not fn.startswith("IO_"):
        return False
    # Config pins double as IO but are driven during configuration.
    if re.search(r"(CCLK|DONE|PROGRAM|INIT_B|TCK|TDI|TDO|TMS|PUDC|EMCCLK|RDWR|CSI)", fn):
        return False
    return bank.isdigit()


def main(argv):
    if len(argv) < 3:
        print(__doc__.strip(), file=sys.stderr)
        return 2
    pins_csv, out = argv[1], argv[2]
    signals = argv[3:] or ["clk", "rst", "led[0]", "led[1]", "led[2]", "led[3]"]

    with open(pins_csv) as f:
        rows = [r for r in csv.DictReader(f) if usable(r)]
    if not rows:
        print(f"{pins_csv}: no usable IO pins found", file=sys.stderr)
        return 1

    # Keep one bank, so a single IOSTANDARD is coherent for the whole design.
    banks = {}
    for r in rows:
        banks.setdefault(r["bank"], []).append(r)
    bank = max(banks, key=lambda b: len(banks[b]))
    pool = sorted(banks[bank], key=lambda r: r["pin"])

    clk_capable = [r for r in pool if re.search(r"_(MRCC|SRCC|GC)", r["pin_function"])]
    if not clk_capable:
        print(f"{pins_csv}: no clock-capable pin in bank {bank}; "
              f"the clock will not route", file=sys.stderr)

    chosen, used = [], set()
    for sig in signals:
        want = clk_capable if (sig == signals[0] and clk_capable) else pool
        for r in want:
            if r["pin"] not in used:
                used.add(r["pin"]); chosen.append((sig, r)); break
        else:
            print(f"{pins_csv}: ran out of pins in bank {bank}", file=sys.stderr)
            return 1

    with open(out, "w") as f:
        f.write(f"# Generated by env/gen_smoke_xdc.py from {pins_csv}\n"
                f"# Arbitrary pin assignment in bank {bank}, for exercising a chipdb.\n"
                f"# NOT a board pinout - do not load the resulting bitstream into hardware.\n")
        for sig, r in chosen:
            f.write(f"# {sig}: {r['site']} {r['pin_function']}\n")
            f.write(f"set_property LOC {r['pin']} [get_ports {sig}]\n")
            f.write(f"set_property IOSTANDARD LVCMOS33 [get_ports {sig}]\n")
    print(f"{out}: bank {bank}, " + ", ".join(f"{s}={r['pin']}" for s, r in chosen))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
